function renderCanvas(){if(windowMode==='tasks')return;const a=byId(state.canvasId);$('#canvas').innerHTML=`<header class="canvas-bar"><div>${orb}<b>Norma OS</b><span>${tr('工作空间画布','Workspace canvas')}</span></div><div>${a?`<button class="canvas-button" data-action="return-inbox">${icon('back')}${t('return')}</button>`:''}<button class="canvas-button" data-action="fit-canvas">${icon('grid')}${tr('全景','Overview')}</button></div></header><div id="canvas-viewport"><div id="canvas-world">${state.items.filter(w=>w.card).map((w,i)=>canvasCard(w,i)).join('')}</div></div><div class="canvas-dock"><button data-action="open-inbox">${orb}<span>Norma</span>${windowMode==='canvas'?icon('out'):''}<span class="dock-count">${state.items.filter(a=>group(a)==='needs').length}</span><kbd>⌘⇧Space</kbd></button><span>${tr('任务、进展与对话，随时呼出','Your tasks, progress and conversations — one shortcut away')}</span></div>`;syncCamera();}
function canvasCard(a,i){const c=ctx(a),focus=state.canvasId===a.id;return `<article class="canvas-card ${focus?'focused':''}" data-card="${a.id}" style="left:${i%3*490}px;top:${Math.floor(i/3)*415}px"><header><span>Agent</span><b>${a.agent}</b><small>${spaceName(a.space)} / ${projects[a.project].name}</small><span class="card-status">${t(a.status)}</span><button data-canvas-chat="${a.id}" title="${tr('在任务页继续','Continue in tasks')}" aria-label="${tr('在任务页继续','Continue in tasks')}">${icon('out')}</button></header><h3>${esc(l(a.title))}</h3><div class="canvas-terminal">${(a.terminal||[['text',l(a.answer)],['muted',l(a.summary)]]).map(([cls,text])=>`<p class="${cls}">${esc(text)}</p>`).join('')}${c.messages.map(m=>`<p class="${m.role==='user'?'cyan':'muted'}">${m.role==='user'?'> ':''}${esc(l(m.text))}</p>`).join('')}</div>${focus?`<form data-form="canvas" class="canvas-input"><textarea data-testid="canvas-input" rows="1" aria-label="${tr('继续这张卡片的会话','Continue this card’s session')}" placeholder="${tr('继续和','Continue with')} ${a.agent}…">${esc(c.draft)}</textarea><button type="submit" data-testid="canvas-send" aria-label="${t('send')}" ${c.draft.trim()?'':'disabled'}>${icon('up')}</button></form>`:`<button class="card-open" data-canvas-chat="${a.id}">${tr('继续沟通','Continue conversation')}${icon('right')}</button>`}</article>`;}
function syncCamera(){const c=state.camera,w=$('#canvas-world');if(w)w.style.transform=`translate(${c.x}px,${c.y}px) scale(${c.z})`;}
function focusCanvasCard(id){const a=byId(id);if(!a?.card)return;state.canvasId=id;const index=state.items.filter(w=>w.card).findIndex(w=>w.id===id),z=Math.min(1.25,(innerWidth-60)/450);state.camera={x:innerWidth/2-(index%3*490+225)*z,y:(innerHeight-130)/2-(Math.floor(index/3)*415+182)*z,z};renderCanvas();$('[data-testid="canvas-input"]')?.focus({preventScroll:true});$('.canvas-card.focused .canvas-terminal').scrollTop=1e6;saveWindowView();}
function locate(){const a=active();if(!a?.card)return;remember();if(windowMode==='tasks'){showPeer('canvas',a.id);return;}hideInbox();focusCanvasCard(a.id);}
function initCanvas(){let pan=null;document.addEventListener('pointerdown',e=>{if($('#inbox').open||!e.target.closest('#canvas-viewport')||e.target.closest('.canvas-card'))return;pan={x:e.clientX,y:e.clientY,cx:state.camera.x,cy:state.camera.y,id:e.pointerId};e.target.setPointerCapture(e.pointerId);});document.addEventListener('pointermove',e=>{if(!pan||e.pointerId!==pan.id)return;state.camera.x=pan.cx+e.clientX-pan.x;state.camera.y=pan.cy+e.clientY-pan.y;syncCamera();});document.addEventListener('pointerup',()=>pan=null);document.addEventListener('pointercancel',()=>pan=null);$('#canvas').addEventListener('wheel',e=>{if($('#inbox').open||e.target.closest('.canvas-terminal'))return;e.preventDefault();const c=state.camera;if(e.metaKey||e.ctrlKey){const z=Math.max(.25,Math.min(1.7,c.z*Math.exp(-e.deltaY*.003))),r=z/c.z;c.x=e.clientX-(e.clientX-c.x)*r;c.y=e.clientY-66-(e.clientY-66-c.y)*r;c.z=z;}else{c.x-=e.deltaX;c.y-=e.deltaY;}syncCamera();},{passive:false});}
